  var root = document.documentElement;
  var listeners = [];
  var lang = SUPPORTED.indexOf(root.lang) >= 0 ? root.lang : 'en';

  // Capture the English page text from the markup.
  Array.prototype.forEach.call(document.querySelectorAll('[data-i18n]'), function (el) {
    var key = el.getAttribute('data-i18n');
    if (!(key in STRINGS.en)) STRINGS.en[key] = el.innerHTML.trim();
  });
  Array.prototype.forEach.call(document.querySelectorAll('[data-i18n-attr]'), function (el) {
    parseAttr(el).forEach(function (p) {
      if (!(p.key in STRINGS.en)) STRINGS.en[p.key] = el.getAttribute(p.attr) || '';
    });
  });

  function parseAttr(el) {
    return el.getAttribute('data-i18n-attr').split(';').map(function (pair) {
      var i = pair.indexOf(':');
      return { attr: pair.slice(0, i).trim(), key: pair.slice(i + 1).trim() };
    });
  }

  function t(key, vars) {
    var dict = STRINGS[lang];
    var value = key in dict ? dict[key] : STRINGS.en[key];
    if (value === undefined) return key;
    if (vars && typeof value === 'string') {
      value = value.replace(/\{(\w+)\}/g, function (m, name) { return name in vars ? vars[name] : m; });
    }
    return value;
  }

  function apply() {
    root.lang = lang;
    Array.prototype.forEach.call(document.querySelectorAll('[data-i18n]'), function (el) {
      var html = t(el.getAttribute('data-i18n'));
      if (el.innerHTML.trim() !== html) el.innerHTML = html;
    });
    Array.prototype.forEach.call(document.querySelectorAll('[data-i18n-attr]'), function (el) {
      parseAttr(el).forEach(function (p) { el.setAttribute(p.attr, t(p.key)); });
    });
    Array.prototype.forEach.call(document.querySelectorAll('[data-set-lang]'), function (b) {
      b.setAttribute('aria-pressed', b.getAttribute('data-set-lang') === lang ? 'true' : 'false');
    });
    root.classList.remove('i18n-pending');
  }

  function setLang(next) {
    if (SUPPORTED.indexOf(next) < 0 || next === lang) return;
    lang = next;
    try { localStorage.setItem(STORAGE_KEY, next); } catch (e) { /* storage unavailable */ }
    apply();
    listeners.forEach(function (fn) { fn(lang); });
  }

  Array.prototype.forEach.call(document.querySelectorAll('[data-set-lang]'), function (b) {
    b.addEventListener('click', function () { setLang(b.getAttribute('data-set-lang')); });
  });

  apply();

  window.i18n = {
    t: t,
    setLang: setLang,
    get lang() { return lang; },
    onChange: function (fn) { listeners.push(fn); },
    _strings: STRINGS
  };
